import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = ctypes.c_void_p()
        self.rows = rows
        self.cols = cols
        self._alloc()

    def _alloc(self):
        ctypes.c_void_p(ctypes.c_int(self.rows), ctypes.c_int(self.cols), ctypes.byref(self.matrix))

    def free(self):
        ctypes.c_void_p(ctypes.c_int(self.rows), ctypes.c_int(self.cols), ctypes.byref(self.matrix))

    def to_numpy(self):
        data = (ctypes.c_double * (self.rows * self.cols)).from_address(self.matrix)
        return np.ctypeslib.as_array(data, shape=(self.rows, self.cols))

    def from_numpy(self, np_array):
        data = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
        ctypes.c_void_p(ctypes.c_int(self.rows), ctypes.c_int(self.cols), ctypes.byref(self.matrix), data)

def gsl_matrix_alloc(rows, cols):
    return GSLMatrix(rows, cols)

def gsl_matrix_free(matrix):
    matrix.free()

def numpy_to_gsl_matrix(np_array):
    matrix = gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])
    matrix.from_numpy(np_array)
    return matrix

def gsl_matrix_to_numpy(gsl_matrix):
    return gsl_matrix.to_numpy()

