    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define the function prototype
    gsl_multifit_covar_func = gsl.gsl_multifit_covar
    gsl_multifit_covar_func.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_void_p]
    gsl_multifit_covar_func.restype = ctypes.c_void_p

    # Call the function
    covar = ctypes.c_void_p()
    gsl_multifit_covar_func(jacobian.matrix, epsrel, ctypes.byref(covar))

