class GSLVector:
    def __init__(self, size):
        self.vector = gsl.gsl_vector_alloc(size)
        self.size = size

    def set_elements(self, values):
        for i in range(self.size):
            gsl.gsl_vector_set(self.vector, i, values[i])

    def get_element(self, index):
        if index < 0 or index >= self.size:
            raise IndexError("Index out of range")
        return gsl.gsl_vector_get(self.vector, index)

    def __del__(self):
        gsl.gsl_vector_free(self.vector)

