        return gsl.gsl_permutation_get(self.ptr, i)


def cholesky_decomposition(input_matrix):
    n = len(input_matrix)
    A = gsl_matrix(n, n)
    P = gsl_permutation(n)

    for i in range(n):
        for j in range(i, n):
            A.set(i, j, input_matrix[i][j])

    gsl.gsl_linalg_pcholesky_decomp(A.ptr, P.ptr)

    result_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            result_matrix[i][j] = A.get(i, j)
            result_matrix[j][i] = A.get(j, i)

    permutation_vector = [P.get(i) for i in range(n)]

    return result_matrix, permutation_vector

