import ctypes
gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class gsl_matrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.size1 = len(matrix)
        self.size2 = len(matrix[0])
        self.data = (ctypes.c_double * (self.size1 * self.size2))()
        for i in range(self.size1):
            for j in range(self.size2):
                self.data[i * self.size2 + j] = matrix[i][j]

class gsl_vector:
    def __init__(self, vector):
        self.vector = vector
        self.size = len(vector)
        self.data = (ctypes.c_double * self.size)()
        for i in range(self.size):
            self.data[i] = vector[i]

def matrix_to_gsl(matrix):
    return gsl_matrix(matrix)

def vector_to_gsl(vector):
    return gsl_vector(vector)

def gsl_matrix_to_list(matrix):
    return [[matrix.data[i * matrix.size2 + j] for j in range(matrix.size2)] for i in range(matrix.size1)]

def gsl_vector_to_list(vector):
    return [vector.data[i] for i in range(vector.size)]

def ql_decomposition_and_unpack(A, tau):
    A_gsl = matrix_to_gsl(A)
    tau_gsl = vector_to_gsl(tau)
    Q_gsl = gsl_matrix([[0] * A_gsl.size1 for _ in range(A_gsl.size1)])
    L_gsl = gsl_matrix([[0] * A_gsl.size2 for _ in range(A_gsl.size1)])
    gsl.gsl_linalg_QL_decomp(A_gsl, tau_gsl)
    gsl.gsl_linalg_QL_unpack(A_gsl, tau_gsl, Q_gsl, L_gsl)
    return gsl_matrix_to_list(Q_gsl), gsl_matrix_to_list(L_gsl)

