class gsl_function(ctypes.Structure):
    _fields_ = [('function', ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p))), ('params', ctypes.POINTER(ctypes.c_void_p))]


def func_wrapper(x, params):
    return py_func(x)


def compute_integral(py_func, a, b, epsabs, epsrel, n):
    func = gsl_function()
    func.function = func_wrapper
    func.params = None
    workspace = gsl.gsl_integration_romberg_alloc(n)
    result, error = ctypes.c_double(), ctypes.c_double()
    status = gsl.gsl_integration_romberg_integrate(ctypes.byref(func), a, b, epsabs, epsrel, workspace, ctypes.byref(result), ctypes.byref(error))
    gsl.gsl_integration_romberg_free(workspace)
    return result.value, status

