class GslRstatQuantileWorkspace:
    def __init__(self):
        self.workspace = None

    def allocate(self):
        self.workspace = gsl.gsl_rstat_quantile_alloc()

    def reset(self):
        gsl.gsl_rstat_quantile_reset(self.workspace)

    def add(self, value):
        gsl.gsl_rstat_quantile_add(self.workspace, value)

    def get(self, p):
        return gsl.gsl_rstat_quantile_get(self.workspace, p)

    def free(self):
        gsl.gsl_rstat_quantile_free(self.workspace)


def compute_quantile(p, values):
    workspace = GslRstatQuantileWorkspace()
    workspace.allocate()
    for value in values:
        workspace.add(value)
    quantile = workspace.get(p)
    workspace.free()
    return quantile

